enum UnitType {
    Province,
    District,
    Ward
}
interface CardSelectAddressBottomProps {
    show: boolean;
    selectProvince: (item: Province) => void;
    selectDistrict: (item: District) => void;
    selectWard: (item: Ward) => void;
    onClose?: () => void;
}
const BottomSheetAddress = (props: CardSelectAddressBottomProps) => {
    const listProvince = useSelector(selectProvinceList) || [];
    const bsRef = useRef<BottomSheetRef>(null);
    const { t } = useTranslation(['module_register']);
    const { show,
        onClose,
        selectProvince,
        selectDistrict,
        selectWard,
    } = props;
    const dispatch = useDispatch();
    const handleSelectWard = (item: Ward) => {
        selectWard(item);
        bsRef.current?.close();
    }
    const handleClose = () => {
        bsRef.current?.close();
    }
    const onShowModal = () => {
        BottomSheetManager.show({
            render: (portalId) => (
                <BottomSheet
                    ref={bsRef}
                    id={portalId}
                    title={t('screen_confirm.lable_bs_address')}
                    onClose={onClose}
                    enableContentPanningGesture={false}
                    snapPoints={['93%']}
                >
                    <FilterAddress listProvince={listProvince} onSelectProvince={selectProvince} onSelectDistrict={selectDistrict} onSelectWard={handleSelectWard} onClose={handleClose} />
                </BottomSheet>
            )
        })
    }
    useEffect(() => {
        if (listProvince.length === 0) {
            dispatch(getProvinceListThunk({ clientNo: '123' }))
        }
    }, []);
    useEffect(() => {
        if (show) {
            onShowModal();
        }
    }, [show]);
    return (
        <View>
        </View>
    );
};
export default BottomSheetAddress;


