import { Spacer, GradientButton, BottomSheetRef } from '@core/ui';
import { FlatList, TouchableOpacity, View } from 'react-native';
import useCSS from '@src/presentation/style';
import BottomSheetPDF from '../bottomSheetPDF';
import { ReactNode, useState, Fragment, useRef } from 'react';
import { useTranslation } from 'react-i18next';

type IPDFItem = {
    id: string;
    title: string;
    content: ReactNode;
    link: string;

};
interface Props {
    onSubmit: () => void;
    data: IPDFItem[];
    onClosePDFView?: () => void;
}

const BottomSheetTnC: React.FC<Props> = ({ onSubmit, data, onClosePDFView, ...props }) => {
    const css = useCSS();
    const { t } = useTranslation(['tnc']);
    const [pdf, setPdf] = useState({
        link: '',
        title: '',
        show: false,
    });
    const handleClosePDFView = () => {
        onClosePDFView?.()
    }
    return (
        <>
            <View style={[css.mv_medium, css.mr_base]}>
                <FlatList
                    data={data}
                    renderItem={({ item, index }) => (
                        <Fragment key={`key-${index}`}>
                            {index > 0 ? <Spacer height={8} /> : null}
                            <View style={[css.row, css.items_center]}>
                                <View style={[css.w_small, css.ratio_square, css.rounded_full, css.bg_red_600, css.mr_base]} />
                                <TouchableOpacity onPress={() => setPdf({ link: item.link, title: item.title, show: true })}>{item?.content}</TouchableOpacity>
                            </View>
                        </Fragment>
                    )}
                    keyExtractor={(item) => item.id}
                    style={{}}
                />
            </View>
            <Spacer height={16} />
            <GradientButton gradientProps={{ type: 'primary' }} title={t('btn_agree')} onPress={onSubmit} />
            <BottomSheetPDF title={pdf.title} show={pdf.show} onClose={handleClosePDFView} link={pdf.link} />
        </>
    );
};

export default BottomSheetTnC;
