import { createAsyncThunk } from '@reduxjs/toolkit';
import { GetProductStatusHandler } from '@src/application/loan_product/queries/get_product_status/get_product_status_handler';
import { container } from '@src/di/inversify.config';
import { TYPES } from '@src/di/types/types';

export const fetchProductStatus = createAsyncThunk('product_status/fetch', async (request: object) => {
    const productStatus = container.get<GetProductStatusHandler>(TYPES.GetProductStatusHandler);
    return await productStatus.handle(request);
});
